import base64
import heapq
import math
import os
import re
import sys
import time
import zlib

# BEGIN LEXICON
LEXICON = ""
# END LEXICON


# ---------------------------------------------------------------- constants
DEADLINE = 7.5          # seconds from assemble() entry
EPS = 0.003             # weight of the letter-trigram fallback model
INPUT_WORD_WEIGHT = 2.0 ** -6
CAMEL_PENALTY = -4.0
NONALPHA_PER_CHAR = math.log(1.0 / 30)
VIOL = -20.0            # text right after padding
SOFT_BAD = -8.0
FLOOR = -12.0           # natural (non-violation) deltas never go below this
MIN_EDGE = 0.5
DERIVE_MIN = 2.0 ** -10
DERIVED = (('s', 0.3), ('ed', 0.15), ('ing', 0.1), ('ly', 0.05), ('es', 0.05))
MAX_H = 14
MAX_W = 60
TOP_PER_SIDE = 6

# ---------------------------------------------------------------- language model
WORD = {}
PRE = {}
SUF = {}
SUB = {}
_LP = {}
_KA = {}
_KB = {}
_DELTA = {}
_LOGT = {}
_TRI = {}
_BI = {}
_UNI = {}
_PAIR = {}
_CTX = {}
_UNI_TOT = 1.0
_LETTERS = 'abcdefghijklmnopqrstuvwxyz'
_STRIP_L = '"\'(['
_STRIP_R = '.,;:!?)"\''
_INTERIOR = re.compile(r'(?<= )\S+(?= )')


def _clean_word(tok):
    return tok.strip(_STRIP_L + _STRIP_R).lower()


def _build_lm(piece_rows):
    """Build the module-level tables. piece_rows: every row of every piece."""
    global _UNI_TOT
    for d in (WORD, PRE, SUF, SUB, _LP, _KA, _KB, _DELTA, _LOGT,
              _TRI, _BI, _UNI, _PAIR, _CTX):
        d.clear()
    weights = {}
    text = zlib.decompress(base64.b64decode(LEXICON)).decode()
    for line in text.split('\n'):
        parts = line.split(' ')
        w = 2.0 ** -int(parts[0])
        for word in parts[1:]:
            weights[word] = weights.get(word, 0.0) + w
    base = list(weights.items())
    for w, x in base:
        if x < DERIVE_MIN or len(w) < 3:
            continue
        for suf, f in DERIVED:
            d = w + suf
            if d not in weights:
                weights[d] = x * f
    for row in piece_rows:
        for tok in _INTERIOR.findall(row):
            t = _clean_word(tok)
            if len(t) >= 2 and t.isalpha() and t.isascii():
                weights[t] = weights.get(t, 0.0) + INPUT_WORD_WEIGHT
    total = sum(weights.values())
    for w, x in weights.items():
        p = x / total
        WORD[w] = p
        n = len(w)
        for i in range(n):
            s = w[:i + 1]
            PRE[s] = PRE.get(s, 0.0) + p
            s = w[n - 1 - i:]
            SUF[s] = SUF.get(s, 0.0) + p
        for i in range(n):
            for j in range(i + 1, min(n, i + 12) + 1):
                s = w[i:j]
                SUB[s] = SUB.get(s, 0.0) + p
        seq = '##' + w + '#'
        for i in range(len(seq) - 2):
            _TRI[seq[i:i + 3]] = _TRI.get(seq[i:i + 3], 0.0) + x
            _BI[seq[i:i + 2]] = _BI.get(seq[i:i + 2], 0.0) + x
        for ch in w:
            _UNI[ch] = _UNI.get(ch, 0.0) + x
        ws = w + '#'
        for i in range(n):
            _PAIR[ws[i:i + 2]] = _PAIR.get(ws[i:i + 2], 0.0) + x
            _CTX[ws[i]] = _CTX.get(ws[i], 0.0) + x
    _UNI_TOT = sum(_UNI.values())


def _p3(ctx, ch):
    return math.log((_TRI.get(ctx + ch, 0.0) + 0.01) / (_BI.get(ctx, 0.0) + 0.27))


def _log_t(s, cl, cr):
    key = (s, cl, cr)
    v = _LOGT.get(key)
    if v is not None:
        return v
    if cl:
        seq = '##' + s
        v = 0.0
        for i in range(2, len(seq)):
            v += _p3(seq[i - 2:i], seq[i])
    else:
        v = math.log((_UNI.get(s[0], 0.0) + 0.01) / (_UNI_TOT + 0.26))
        for i in range(1, len(s)):
            if i == 1:
                v += math.log((_PAIR.get(s[:2], 0.0) + 0.01) / (_CTX.get(s[0], 0.0) + 0.27))
            else:
                v += _p3(s[i - 2:i], s[i])
    if cr:
        if len(s) == 1 and not cl:
            v += math.log((_PAIR.get(s + '#', 0.0) + 0.01) / (_CTX.get(s, 0.0) + 0.27))
        else:
            v += _p3(('##' + s)[-2:], '#')
    _LOGT[key] = v
    return v


def _lp_part(part, cl, cr):
    v = 0.0
    for i in range(1, len(part)):
        if part[i].isupper() and part[i - 1].islower():
            v += CAMEL_PENALTY
            break
    low = part.lower()
    if not (low.isalpha() and low.isascii()):
        return v + NONALPHA_PER_CHAR * len(part)
    if cl:
        m = (WORD if cr else PRE).get(low, 0.0)
    else:
        m = (SUF if cr else SUB).get(low, 0.0)
    return v + math.log(m + EPS * math.exp(_log_t(low, cl, cr)))


def lp(tok, cl, cr):
    key = (tok, cl, cr)
    v = _LP.get(key)
    if v is not None:
        return v
    t = tok
    t2 = t.lstrip(_STRIP_L)
    if len(t2) != len(t):
        cl = True
    t = t2.rstrip(_STRIP_R)
    if len(t) != len(t2):
        cr = True
    if not t:
        v = 0.0
    else:
        parts = t.split('-')
        last = len(parts) - 1
        v = 0.0
        for i, part in enumerate(parts):
            if not part:
                continue
            pcl = cl if i == 0 else True
            pcr = cr if i == last else False
            v += _lp_part(part, pcl, pcr)
    _LP[key] = v
    return v


def key_a(a):
    k = _KA.get(a)
    if k is None:
        ta = a.rstrip(' ')
        trail = min(len(a) - len(ta), 2)
        if not ta:
            k = ('', False, trail)
        else:
            k = (ta.rsplit(' ', 1)[-1], ' ' in ta, trail)
        _KA[a] = k
    return k


def key_b(b):
    k = _KB.get(b)
    if k is None:
        tb = b.lstrip(' ')
        lead = min(len(b) - len(tb), 2)
        if not tb:
            k = ('', False, lead)
        else:
            k = (tb.split(' ', 1)[0], ' ' in tb, lead)
        _KB[b] = k
    return k


def delta_keys(ka, kb):
    key = (ka, kb)
    v = _DELTA.get(key)
    if v is not None:
        return v
    ta, ca, trail = ka
    tb, cb, lead = kb
    a_empty = not ta
    b_empty = not tb
    s = trail + lead
    if s >= 2:
        v = 0.0 if b_empty else VIOL
    elif s == 1:
        v = 0.0
        if not a_empty:
            v += lp(ta, ca, True) - lp(ta, ca, False)
        if not b_empty:
            v += lp(tb, True, cb) - lp(tb, False, cb)
    elif a_empty or b_empty:
        v = 0.0
    else:
        tri = []
        for g in (ta[-2:] + tb[:1], ta[-1:] + tb[:2]):
            g = g.lower()
            if len(g) == 3 and g.isalpha() and g.isascii():
                tri.append(g)
        if tri and all(g not in SUB for g in tri):
            v = SOFT_BAD
        else:
            v = lp(ta + tb, ca, cb) - lp(ta, ca, False) - lp(tb, False, cb)
    if v < FLOOR and v > VIOL:
        v = FLOOR
    _DELTA[key] = v
    return v


def delta_row(a, b):
    if not a or not b:
        return 0.0
    return delta_keys(key_a(a), key_b(b))


# ---------------------------------------------------------------- clusters
_NEG = -10 ** 9


class _Cl(object):
    __slots__ = ('id', 'R', 'n', 'places', 'r0', 'c0', 'r1', 'c1', 'ver', 'fr')

    def __init__(self, cid):
        self.id = cid
        self.R = {}
        self.n = 0
        self.places = []
        self.r0 = self.c0 = 0
        self.r1 = self.c1 = 0
        self.ver = 0
        self.fr = None

    def rebox(self):
        rs = [r for r, row in self.R.items() if row]
        self.r0 = min(rs)
        self.r1 = max(rs) + 1
        self.c0 = min(min(row) for row in self.R.values() if row)
        self.c1 = max(max(row) for row in self.R.values() if row) + 1


def _single(pid, rows, cid):
    cl = _Cl(cid)
    for r, row in enumerate(rows):
        cl.R[r] = dict(enumerate(row))
    cl.n = len(rows) * len(rows[0])
    cl.places.append((pid, 0, 0))
    cl.r1 = len(rows)
    cl.c1 = len(rows[0])
    return cl


def _overlap(X, Y, dr, dc):
    """True if Y shifted by (dr, dc) collides with X."""
    if Y.n > X.n:
        X, Y, dr, dc = Y, X, -dr, -dc
    XR = X.R
    for r, row in Y.R.items():
        xrow = XR.get(r + dr)
        if xrow:
            for c in row:
                if c + dc in xrow:
                    return True
    return False


def merge_eval(X, Y, dr, dc):
    """Evidence gain for placing Y at (dr, dc) in X coordinates, or None if illegal."""
    if (max(X.r1, Y.r1 + dr) - min(X.r0, Y.r0 + dr) > MAX_H
            or max(X.c1, Y.c1 + dc) - min(X.c0, Y.c0 + dc) > MAX_W):
        return None
    if _overlap(X, Y, dr, dc):
        return None
    gain = 0.0
    XR = X.R
    for ry, yrow in Y.R.items():
        xrow = XR.get(ry + dr)
        if not xrow:
            continue
        cols = sorted(set(xrow).union([c + dc for c in yrow]))
        # padding rule
        dbl = False
        pc = _NEG
        pch = ''
        for c in cols:
            ch = xrow.get(c)
            if ch is None:
                ch = yrow[c - dc]
            if ch != ' ':
                if dbl:
                    return None
            elif pch == ' ' and c == pc + 1:
                dbl = True
            pc = c
            pch = ch
        # run gains
        pc = _NEG
        segs = []
        cur = []
        corg = -1
        for c in cols:
            ch = xrow.get(c)
            if ch is None:
                ch = yrow[c - dc]
                org = 1
            else:
                org = 0
            if c != pc + 1:
                if len(segs) > 0:
                    segs.append(''.join(cur))
                    gain = _run_gain(segs, gain)
                    if gain is None:
                        return None
                segs = []
                cur = [ch]
            elif org != corg:
                segs.append(''.join(cur))
                cur = [ch]
            else:
                cur.append(ch)
            corg = org
            pc = c
        if segs:
            segs.append(''.join(cur))
            gain = _run_gain(segs, gain)
            if gain is None:
                return None
    return gain


def _run_gain(segs, gain):
    acc = segs[0]
    for seg in segs[1:]:
        g = delta_row(acc, seg)
        if g <= VIOL + 1:
            return None
        gain += g
        acc += seg
    return gain


# ---------------------------------------------------------------- state
_T0 = 0.0
_PROWS = []
_PW = []
_CL = {}
_WHERE = {}
_VER = [0]


def _late():
    return time.perf_counter() - _T0 > DEADLINE


def _merge(X, Y, dr, dc, swap=True):
    """Absorb the smaller cluster into the larger. Y sits at (dr, dc) in X coordinates."""
    if swap and Y.n > X.n:
        X, Y, dr, dc = Y, X, -dr, -dc
    XR = X.R
    for r, row in Y.R.items():
        xrow = XR.get(r + dr)
        if xrow is None:
            xrow = XR[r + dr] = {}
        for c, ch in row.items():
            xrow[c + dc] = ch
    X.n += Y.n
    for pid, r, c in Y.places:
        X.places.append((pid, r + dr, c + dc))
        _WHERE[pid] = (X.id, r + dr, c + dc)
    X.r0 = min(X.r0, Y.r0 + dr)
    X.r1 = max(X.r1, Y.r1 + dr)
    X.c0 = min(X.c0, Y.c0 + dc)
    X.c1 = max(X.c1, Y.c1 + dc)
    _VER[0] += 1
    X.ver = _VER[0]
    X.fr = None
    _CL.pop(Y.id, None)
    return X


# ---------------------------------------------------------------- candidates + greedy merge
def _alpha(ch):
    return ch.isalpha() and ch.isascii()


def _candidates():
    ra = {}
    rb = {}
    for pid, rows in enumerate(_PROWS):
        for i, row in enumerate(rows):
            ra.setdefault(key_a(row), []).append((pid, i))
            rb.setdefault(key_b(row), []).append((pid, i))
    kbs = [k for k in rb if k[2] == 0 and k[0] and _alpha(k[0][0])]
    g1 = {}
    g2 = {}
    for kb in kbs:
        t = kb[0].lower()
        g1.setdefault(t[0], []).append(kb)
        if len(t) >= 2 and _alpha(t[1]):
            g2.setdefault(t[:2], []).append(kb)
    positive = {}
    for ka in ra:
        tok = ka[0]
        if ka[2] != 0 or not tok or not _alpha(tok[-1]):
            continue
        t = tok.lower()
        if len(t) < 2 or not _alpha(t[-2]):
            cand = kbs
        else:
            cs = set()
            t2 = t[-2:]
            for x, lst in g1.items():
                if t2 + x in SUB:
                    cs.update(lst)
            t1 = t[-1]
            for xy, lst in g2.items():
                if t1 + xy in SUB:
                    cs.update(lst)
            cand = cs
        pos = [kb for kb in cand if delta_keys(ka, kb) > 0]
        if pos:
            positive[ka] = pos
    triples = set()
    for ka, pos in positive.items():
        for pa, i in ra[ka]:
            for kb in pos:
                for pb, j in rb[kb]:
                    if pb != pa:
                        triples.add((pa, pb, i - j))
    best_a = {}
    best_b = {}
    for A, B, d in triples:
        ra_, rb_ = _PROWS[A], _PROWS[B]
        e = 0.0
        for i in range(len(ra_)):
            j = i - d
            if 0 <= j < len(rb_):
                e += delta_row(ra_[i], rb_[j])
        if e <= MIN_EDGE:
            continue
        best_a.setdefault(A, []).append((e, A, B, d))
        best_b.setdefault(B, []).append((e, A, B, d))
    keep = set()
    for lst in list(best_a.values()) + list(best_b.values()):
        lst.sort(reverse=True)
        keep.update(lst[:TOP_PER_SIDE])
    return list(keep)


def _greedy(entries):
    heap = [(-e, A, B, d, 0, 0) for e, A, B, d in entries]
    heapq.heapify(heap)
    k = 0
    while heap:
        k += 1
        if k & 63 == 0 and _late():
            break
        _, A, B, d, va, vb = heapq.heappop(heap)
        cx, rA, cA = _WHERE[A]
        cy, rB, cB = _WHERE[B]
        if cx == cy:
            continue
        X = _CL[cx]
        Y = _CL[cy]
        dr = rA + d - rB
        dc = cA + _PW[A] - cB
        m = merge_eval(X, Y, dr, dc)
        if m is None or m <= MIN_EDGE:
            continue
        if (X.ver == va and Y.ver == vb) or not heap or m >= -heap[0][0]:
            _merge(X, Y, dr, dc)
        else:
            heapq.heappush(heap, (-m, A, B, d, X.ver, Y.ver))


# ---------------------------------------------------------------- driver
def _output():
    out = []
    for cl in _CL.values():
        if not cl.places:
            continue
        r0 = min(r for _, r, _ in cl.places)
        c0 = min(c for _, _, c in cl.places)
        for pid, r, c in cl.places:
            out.append([pid, cl.id, r - r0, c - c0])
    out.sort()
    return out


def assemble(pieces):
    global _T0, _PROWS, _PW
    _T0 = time.perf_counter()
    _PROWS = [p.replace('_', ' ').split('|') for p in pieces]
    _PW = [len(rows[0]) for rows in _PROWS]
    _build_lm([r for rows in _PROWS for r in rows])
    _CL.clear()
    _WHERE.clear()
    for pid, rows in enumerate(_PROWS):
        _CL[pid] = _single(pid, rows, pid)
        _WHERE[pid] = (pid, 0, 0)
    _greedy(_candidates())
    return _output()


if __name__ == '__main__':
    fptr = open(os.environ['OUTPUT_PATH'], 'w')
    pieces_count = int(input().strip())
    pieces = []
    for _ in range(pieces_count):
        pieces.append(input())
    result = assemble(pieces)
    fptr.write('\n'.join(map(lambda x: ' '.join(map(str, x)), result)))
    fptr.write('\n')
    fptr.close()
